def extrair_tabela(soup, grid_id):
    grid = soup.find("table", {"id": grid_id})
    if not grid:
        return {}
    
    dados = {}
    rows = grid.find_all("tr")[1:]  # Pula o cabeçalho
    for row in rows:
        cols = [td.get_text(strip=True) for td in row.find_all("td")]
        if len(cols) >= 5:
            versao, codigo, descricao, comentario, quantidade = cols[:5]
            dados[codigo] = {
                "versao": versao,
                "descricao": descricao,
                "comentario": comentario,
                "quantidade": quantidade
            }
    return dados

def executar_teste():
    print("[1] Processando HTML do sistema ASP.NET...")
    soup = BeautifulSoup(html_data, "html.parser")

    # Extrai dados da Versao 55 (GridView1) e Versao 54 (GridView2)
    v55_data = extrair_tabela(soup, "GridView1")
    v54_data = extrair_tabela(soup, "GridView2")

    if not v55_data or not v54_data:
        print("[ERRO] Nao foi possivel localizar as tabelas de comparacao no HTML.")
        return

    print(f"[2] Itens lidos: Versao 55 ({len(v55_data)} itens) | Versao 54 ({len(v54_data)} itens)")
    print("[3] Comparando componentes entre as versoes...\n")

    divergencias = []
    
    # Compara v55 contra v54
    todos_codigos = set(v55_data.keys()).union(set(v54_data.keys()))

    for codigo in todos_codigos:
        item_v55 = v55_data.get(codigo)
        item_v54 = v54_data.get(codigo)

        if item_v55 and item_v54:
            if item_v55["quantidade"] != item_v54["quantidade"]:
                divergencias.append({
                    "tipo": "QTD_DIVERGENTE",
                    "codigo": codigo,
                    "descricao": item_v55["descricao"],
                    "v55_qtd": item_v55["quantidade"],
                    "v54_qtd": item_v54["quantidade"]
                })
        elif item_v55 and not item_v54:
            divergencias.append({
                "tipo": "APENAS_V55",
                "codigo": codigo,
                "descricao": item_v55["descricao"],
                "v55_qtd": item_v55["quantidade"],
                "v54_qtd": "N/A"
            })
        elif not item_v55 and item_v54:
            divergencias.append({
                "tipo": "APENAS_V54",
                "codigo": codigo,
                "descricao": item_v54["descricao"],
                "v55_qtd": "N/A",
                "v54_qtd": item_v54["quantidade"]
            })

    # Exibe o resultado no terminal
    if divergencias:
        print("==================================================")
        print("    [RESULTADO]: DIVERGÊNCIAS ENCONTRADAS!")
        print("==================================================")
        for d in divergencias:
            print(f"Código Protheus : {d['codigo']}")
            print(f"Descrição        : {d['descricao']}")
            print(f"Qtd Versão 55    : {d['v55_qtd']}")
            print(f"Qtd Versão 54    : {d['v54_qtd']}")
            print(f"Tipo Diferença   : {d['tipo']}")
            print("-" * 50)
    else:
        print("==================================================")
        print("    [RESULTADO]: NENHUMA DIVERGÊNCIA ENCONTRADA.")
        print("==================================================")

if __name__ == "__main__":
    executar_teste()